$fn = 48;
span = 180;
depth = 36;
panel_count = 6;
member_width = 6;
member_depth = 8;
gusset_radius = 9;
gusset_thickness = 2;
bolt_diameter = 2.5;

module member_between(p1, p2, w=member_width, d=member_depth) {
  dx = p2[0] - p1[0];
  dz = p2[1] - p1[1];
  L = sqrt(dx*dx + dz*dz);
  a = atan2(dz, dx);
  translate([(p1[0]+p2[0])/2, 0, (p1[1]+p2[1])/2])
    rotate([0, -a, 0]) cube([L, d, w], center=true);
}

module gusset_at(p) {
  difference() {
    translate([p[0], 0, p[1]]) cylinder(h=gusset_thickness, r=gusset_radius, center=true);
    translate([p[0], 0, p[1]]) cylinder(h=gusset_thickness+1, d=bolt_diameter, center=true);
  }
}

module support_pad(x) {
  translate([x, 0, -member_width]) cube([20, member_depth + 10, 3], center=true);
}

module simple_panel_truss() {
  pl = span / panel_count;
  union() {
    for (i=[0:panel_count-1]) {
      member_between([-span/2+i*pl,0], [-span/2+(i+1)*pl,0]);
      member_between([-span/2+i*pl,depth], [-span/2+(i+1)*pl,depth]);
    }
    for (i=[0:panel_count]) {
      x = -span/2 + i*pl;
      member_between([x,0], [x,depth]);
      gusset_at([x,0]);
      gusset_at([x,depth]);
    }
    support_pad(-span/2);
    support_pad(span/2);
  }
}

simple_panel_truss();

