module member_between(p1, p2, w=member_width, d=member_depth) { dx=p2[0]-p1[0]; dz=p2[1]-p1[1]; L=sqrt(dx*dx+dz*dz); a=atan2(dz,dx); translate([(p1[0]+p2[0])/2,0,(p1[1]+p2[1])/2]) rotate([0,-a,0]) cube([L,d,w], center=true); }
module gusset_at(p) { difference() { translate([p[0],0,p[1]]) cylinder(h=gusset_thickness, r=gusset_radius, center=true); translate([p[0],0,p[1]]) cylinder(h=gusset_thickness+1, d=bolt_diameter, center=true); } }
module support_pad(x) { translate([x,0,-member_width]) cube([20, member_depth+10, 3], center=true); }
module pratt_howe_truss() { pl=span/panel_count; union() { for(i=[0:panel_count-1]) { x0=-span/2+i*pl; x1=x0+pl; member_between([x0,0],[x1,0]); member_between([x0,depth],[x1,depth]); pratt_left = i < panel_count/2; if(use_pratt) { if(pratt_left) member_between([x0,0],[x1,depth]); else member_between([x0,depth],[x1,0]); } else { if(pratt_left) member_between([x0,depth],[x1,0]); else member_between([x0,0],[x1,depth]); } } for(i=[0:panel_count]) { x=-span/2+i*pl; member_between([x,0],[x,depth]); gusset_at([x,0]); gusset_at([x,depth]); } support_pad(-span/2); support_pad(span/2); } }
